def load(p):
    try:
        x=json.loads(p.read_text(encoding='utf-8')); return x if isinstance(x,dict) else {}
    except Exception:return {}
def clean(v):return str(v or '').upper().replace('USDT','').replace('$','').strip()
def main():
    p=load(PREFLIGHT); d=p.get('content_director_4') or {}; selected=p.get('selected_opportunity') or {}; feedback=load(FEEDBACK); fmt=str(d.get('recommended_format') or 'TOP MOVERS').upper(); narrative=str(d.get('narrative_engine') or 'what_to_watch'); sym=clean(selected.get('symbol') or (d.get('primary_story') or {}).get('symbol'))
    if not re.fullmatch(r'[A-Z0-9]{1,15}',sym):raise SystemExit('Script Director: authoritative selected symbol is missing or invalid')
    style=ARCHETYPES.get(narrative,'conversational'); learned=(feedback.get('learned_preferences') or {}).get('style') or {}; learned_style=str(learned.get('prefer') or '').strip().lower()
    if learned_style and int(learned.get('sample') or 0)>=5 and learned_style in set(ARCHETYPES.values()): style=learned_style
    hooks=[h.replace('${symbol}',f'${sym}') for h in HOOKS.get(style,HOOKS['conversational'])]
    qs=QUESTIONS.get(style,QUESTIONS['conversational']); seed=hashlib.sha256((sym+fmt+narrative+style).encode()).hexdigest(); qidx=int(seed[:8],16)%len(qs)
    news_title=str(selected.get('news_title') or '').strip(); news_source=str(selected.get('news_source') or '').strip(); story=(d.get('primary_story') or {})
    directive={'version':'5.7','format':fmt,'primary_symbol':sym,'narrative_engine':narrative,'creator_archetype':style,'news_title':news_title,'news_source':news_source,'performance_learning':{'preferred_style':learned_style or None,'style_sample':learned.get('sample',0),'preferred_hook_type':((feedback.get('learned_preferences') or {}).get('hook_type') or {}).get('prefer')},'hook_candidates':hooks,'question_candidates':qs,'writing_contract':['Write one finished Binance Square post, never an outline, briefing or instructions.','The post must feel written by a sharp human creator with a point of view, not a market-data bot.','Build an information gap in the opening: give the reader one concrete fact but leave a clear reason to keep reading.','Within the first 2 lines, answer why this specific story is interesting NOW without using filler phrases.','Use a 4-beat structure when appropriate: HOOK → NEW INFORMATION → INTERPRETATION → DECISION/QUESTION. For technical stories use HOOK → EVIDENCE → LEVEL/SCENARIO → QUESTION. For news use EVENT → WHY IT MATTERS → MARKET REACTION → QUESTION.','Every paragraph must add a new fact, implication, comparison or decision. Never restate the headline.','Prefer one memorable number, level, contrast or unexpected implication over a pile of statistics.','Create a real conversation trigger: A/B choice, bull/bear test, breakout/fakeout, chase/pullback/wait, agreement/disagreement, or a precise follow-up question.','Never use generic engagement bait such as “What do you think?”, “Thoughts?”, “Who agrees?”, “Like and follow”, or “Comment below”.','Use exactly one question, at the end. The question must be answerable quickly from the post and should invite a position, not a vague opinion.','For NEWSROOM: state the verified event and source naturally, then explain the market implication. Do not turn news into a generic price recap.','For TECHNICAL: make the TradingView chart evidence, not decoration; use only supplied current levels and explain confirmation/invalidation.','For MOMENTUM: explain why the move is notable beyond its percentage and focus on follow-through.','For DATA: connect at least two supplied measurements or explain why one number changes the read.','For ACCOUNTABILITY: identify the original public creator call only when supplied, then measure the actual outcome; never rewrite history.','For DEBATE: present two legitimate interpretations before asking the reader to choose.','For TEACHER: teach one reusable chart-reading principle, not a definition dump.','For UPDATE: state what changed and what remains unresolved.','Use short mobile-first paragraphs, varied sentence rhythm and natural punctuation.','Do not force emojis. Use at most two, and only when they improve the hook.','Use exact supplied evidence only. Never invent prices, volume, targets, stops, sources, creator calls or outcomes.','Targets, stops and 10x/20x scenarios are conditional only and require supporting data.','Do not imitate another creator. Learn structures, not identity or wording.','Never promise profit, certainty, guaranteed returns or guaranteed virality.'],'retention_rules':['The opening must create curiosity, tension, surprise, contrast or a decision.','Do not start every post with ticker + percentage.','Do not use the same CTA mechanism in consecutive cycles when history is available.','Make the reader feel there is a payoff in the next paragraph.','When a story has a natural follow-up, leave a clear reason to return for the next update.'],'anti_template_rules':['Reject “fresh check”, “quick market check”, “here is what matters”, “the next reaction matters” as standalone generic openings.','Reject repeated “Bull case / Bear case” blocks unless the selected format genuinely benefits from scenarios.','Reject sentences that merely instruct the reader to use verified data; the post must contain the supplied data itself.'] ,'story_inputs':{'primary_story':story,'authoritative_selection':selected,'news_title':news_title,'news_source':news_source},'recommended_question_index':qidx}
    OUT.parent.mkdir(parents=True,exist_ok=True); OUT.write_text(json.dumps(directive,indent=2,ensure_ascii=False),encoding='utf-8'); p['script_director_4']=directive; p['content_director_instruction']=f'Use authoritative asset ${sym}, format {fmt}, narrative engine {narrative}, archetype {style}, and TradingView visual package {story.get("chart_symbols") or [sym]}.'; PREFLIGHT.write_text(json.dumps(p,indent=2,ensure_ascii=False),encoding='utf-8'); print(json.dumps({'status':'OK','version':'5.7','format':fmt,'symbol':sym,'narrative_engine':narrative,'creator_archetype':style},indent=2))
